(p/'FINDINGS.md').write_text(s.replace('(../','(../../'))
m['release_outcome']='Application-only flash verified; first operator-reported unaided success, all 1203 rows/checksums saved; afterward disarmed/calibrated, trim 3.16. Firmware unchanged.'
m['first_success_log']=new['file']
for name in ('device-checks.json','FINDINGS.md'):
 b=(p/name).read_bytes();m['files'][name]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
