identity.update(application=m['files']['firmware.bin'],local_package='artifacts/balance-startup-recovery',first_success_log='telemetry_logs/'+new['file'],first_success_file_checksum=new['file_checksum'],first_success_usb_checksum=new['usb_checksum'],physical_validation='One operator-reported successful unaided trial, supported by complete telemetry; repeatability pending')
(e/'tested-firmware-identity.json').write_text(json.dumps(identity,indent=2)+'\n')
